const request=validateSdkRequest({requestId:p.requestId,method:p.method,args:decodeValue(p.argsWire),deadlineAt:p.deadlineAt});
const admission=await f.authority.admitSdk(request,f.sender);
await f.storage.executeSdk(request.method,request.args,admission.context);
const restarted=f.makeAuthority(); await restarted.recoverSdk();
const broker=f.makeBroker(restarted); console.log(decodeValue((await broker.request(p,f.sender)).valueWire));
console.log(await f.rows('runs')); console.log((await f.rows('commandJournal')).find(x=>x.tag==='sdk-operation'));
broker.dispose(); f.broker.dispose();

